<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use Vendi\Database\Connection;use Vendi\Auth\AuthService;
session_start();$error='';
if(isset($_SESSION['user'])){header('Location: index.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$db=Connection::get();$bid=(int)($_POST['business_id']??0);$u=(new AuthService($db))->attempt($bid,(string)($_POST['email']??''),(string)($_POST['password']??''));if(!$u)$error='Datos de acceso incorrectos.';else{session_regenerate_id(true);$_SESSION['user']=$u;$_SESSION['active_branch_id']=(int)($u['default_branch_id']??0);header('Location: index.php');exit;}}catch(Throwable$e){$error='No fue posible iniciar sesión. Revisa la instalación.';}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceder · Vendi POS</title><style>body{font-family:system-ui;background:#f5f7fb;display:grid;place-items:center;min-height:100vh;margin:0}.box{width:min(390px,90vw);background:#fff;padding:32px;border-radius:18px;box-shadow:0 10px 35px #0001}input,button{box-sizing:border-box;width:100%;padding:13px;margin:7px 0;border:1px solid #d7dce5;border-radius:9px}button{background:#111827;color:white;border:0;font-weight:700}.brand{font-size:28px;font-weight:800}.brand span{color:#2563eb}.err{background:#fee2e2;padding:10px;border-radius:8px}</style></head><body><form class="box" method="post"><div class="brand">Vendi<span>POS</span></div><p>Accede a tu punto de venta</p><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?><input name="business_id" type="number" min="1" value="1" required placeholder="Negocio"><input name="email" type="email" required autocomplete="username" placeholder="Correo"><input name="password" type="password" required autocomplete="current-password" placeholder="Contraseña"><button>Entrar</button></form></body></html>